#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1)
            res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long a) {
    return modPow(a, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> factorials(n + 1);
    factorials[0] = 1;
    for (int i = 1; i <= n; i++) {
        factorials[i] = (factorials[i - 1] * i) % MOD;
    }
    if (k == 0) {
        cout << factorials[n] << "\n";
        return 0;
    }
    int c = n - (int)k;
    long long invFactC = modInverse(factorials[c]);
    long long invFactNMinusC = modInverse(factorials[n - c]);
    long long answer = factorials[n] * invFactC % MOD * invFactNMinusC % MOD;
    long long total = 0;
    for (int i = 0; i <= c; i++) {
        long long term;
        if (i % 2 == 0) {
            long long temp = factorials[c] * modInverse(factorials[i]) % MOD;
            temp = temp * modInverse(factorials[c - i]) % MOD;
            temp = temp * modPow(c - i, n) % MOD;
            total = (total + temp) % MOD;
        } else {
            long long temp = factorials[c] * modInverse(factorials[i]) % MOD;
            temp = temp * modInverse(factorials[c - i]) % MOD;
            temp = temp * modPow(c - i, n) % MOD;
            total = (total - temp + MOD) % MOD;
        }
    }
    answer = answer * 2 % MOD * total % MOD;
    cout << answer << "\n";
    return 0;
}

